pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime) public {
        // bound unlockTime to represent realistic future/current values (wide enough to include 0 and block.timestamp)
        unlockTime = bound(unlockTime, 0, type(uint256).max);

        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        vm.warp(1000);
        c.Put{value: 1 ether}(unlockTime);

        // The general rule: after a Put, the unlockTime for the caller must be either >= block.timestamp
        // or exactly the provided unlockTime if it was > block.timestamp. Given the semantics, the stored
        // unlockTime should never be 0 unless the provided unlockTime was 0 and block.timestamp == 0 (which we avoid).
        // Because we warped to 1000, block.timestamp > 0, so the unlockTime must be >= 1000 or equal to unlockTime if > 1000.
        // The bug sets it to 0, which is always < block.timestamp, violating this invariant.
        (, uint storedBalance, uint storedUnlockTime) = c.Acc(caller);
        assertTrue(storedUnlockTime >= block.timestamp || storedUnlockTime == unlockTime);
    }
}

