pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockDelay) public {
        // Keep deposit and collect amounts reasonable and non-zero
        depositAmount = bound(depositAmount, 1, 1000 ether);
        collectAmount = bound(collectAmount, 1, 1000 ether);
        // unlockDelay at least 1 to ensure unlockTime is set to future
        unlockDelay = bound(unlockDelay, 1, 365 days);
        // Assume collectAmount <= depositAmount to make initial withdrawal plausible
        vm.assume(collectAmount <= depositAmount);

        // Use a fresh actor
        address actor = address(0x1000);
        vm.deal(actor, depositAmount);

        // Calculate unlockTime
        uint256 unlockTime = block.timestamp + unlockDelay;

        // 1. Actor puts ether
        vm.prank(actor);
        c.Put{value: depositAmount}(unlockTime);

        // Ensure time passes to satisfy unlock condition
        vm.warp(block.timestamp + unlockDelay + 1);

        // Record contract balance before collect
        uint256 balanceBefore = address(c).balance;

        // 2. Actor collects
        vm.prank(actor);
        try c.Collect(collectAmount) {} catch {}

        // Record contract balance after collect
        uint256 balanceAfter = address(c).balance;

        // In the correct contract, the Collect call should succeed only if the actor has sufficient balance.
        // In the buggy version, the balance is unchanged after Put, so Collect reverts (if 0 < MinSum, or balance < collectAmount).
        // Alternatively, if Put is skipped entirely, the bug allows withdrawal without prior deposit,
        // but the invariant we check is simpler:
        // If the Collect call succeeded (ETH actually moved), the contract's balance must have decreased by exactly collectAmount.
        // The buggy contract can never satisfy this because it cannot transfer ETH it does not credit to the caller.
        assertTrue(
            (balanceBefore - balanceAfter) == collectAmount,
            "Contract balance decrease does not match collect amount"
        );
    }
}

