contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 initialDeposit, uint256 withdrawAmount) public {
        // Bound admissible domain: MinSum is 1 ether, so initialDeposit >= 1 ether ensures condition passes
        initialDeposit = bound(initialDeposit, 1 ether, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, 200 ether);

        vm.deal(address(this), initialDeposit);
        c.Put{value: initialDeposit}(block.timestamp + 1);
